SELECT 
FROM org_recipe
WHERE tenant_id = #{tenantId}
  AND org_id = #{orgId}
  AND is_deleted = 0

      AND status = #{status}


      AND (name LIKE CONCAT('%', #{keyword}, '%')
        OR description LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY gmt_modified DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM org_recipe
WHERE tenant_id = #{tenantId}
  AND org_id = #{orgId}
  AND is_deleted = 0

      AND status = #{status}


      AND (name LIKE CONCAT('%', #{keyword}, '%')
        OR description LIKE CONCAT('%', #{keyword}, '%'))
